schemas.content:
section data: DelimitedWithHeadings
{
  scope.untilEof;
  delimiter: ',';

  Record
  {
    Name            : STRING;
    Employed        : INTEGER(optional);
    IQ              : INTEGER(optional);
    'Weight KG'     : DECIMAL(optional);
    'DATE OF BIRTH' : DATE;
    TIME_OF_DEATH   : DATETIME;
  }
}
